import {createAncientTree} from '../src/trees.js';
function start(){const api=window.__plantStudy;if(!api?.study)return;const dead=new URLSearchParams(location.search).get('case')==='05',id=dead?'05':'03',tree=createAncientTree({dead,bark:false});api.mount(tree,{id,view:{target:[0,dead?3:9,0],yaw:.28,pitch:1.46,distance:dead?15:45,nearTarget:dead?[0,2,.2]:[-.1,12,.2],nearDistance:dead?3.7:8},ground:true,background:0x353c36,environmentIntensity:0,neutralStudio:true,ambient:.75,rim:.7,fog:dead?[25,85]:[60,150],shadowRadius:dead?6:13,time:0,dof:0});api.params.light=315;document.querySelector('#light').value=315;document.querySelector('#light').dispatchEvent(new Event('input'));api.setTime(0);document.querySelector('#reset').click();document.title=`植被自习${id} · 骨架与生长坐标检查`;document.querySelector('.edition').textContent=`STUDY ${id} · STRUCTURE R03`;document.querySelector('.brand small').textContent=`VEGETATION · FIELD NOTES ${id}`;document.querySelector('#cases').innerHTML=`<button class="active">${id} ${dead?'枯枝骨架':'古松骨架'}</button>`;document.querySelector('#title').textContent=dead?'枝干的转折':'先看树的骨架';document.querySelector('#subtitle').textContent=dead?'中空劈裂 · 父子附着 · 末梢渐细':'扭干 · 分层侧枝 · 1.7米人物尺度';document.querySelector('.scene-caption').classList.add('dark');document.querySelector('aside h2').textContent='灰模检查，树皮暂不验收';document.querySelector('aside > .muted').textContent='用中性材质检查枝干走向、空洞和层级。真实几何允许任意旋转；不会用失败的树皮材质遮住结构。现有骨架仍须对照原参考验形。';document.querySelector('.segmented').hidden=true;document.querySelector('#leaf-parameters').hidden=true;document.querySelector('#reference-macro').hidden=true;document.querySelector('.timeline').hidden=true;const e=tree.evidence();document.querySelector('#evidence-summary').textContent=`${e.axes} 条轴的父子连接与累计弧长坐标已检查。原作者工程未取得；04树皮材质未应用。`;document.querySelector('.evidence b').textContent='结构候选 · 无3A验收';if(!dead){const label=document.createElement('label');label.className='check';label.innerHTML='<input type="checkbox" id="needles" checked>显示独立针叶';document.querySelector('.evidence').before(label);document.querySelector('#needles').onchange=ev=>{tree.setNeedles(ev.target.checked);api.invalidate();};}document.querySelector('#source-dialog').innerHTML='<button class="close" id="tree-source-close">关闭</button><h2>骨架老师与自习边界</h2><p>历史母体1.14的原 TreeDevelopmentGenerator 与原随机数函数已运行，固定样例138条轴、137条父子连接逐一核对，只有末级轴允许挂叶。完整原文件未修改。</p><p>此页借用父切线引导、逐级分枝、弧长坐标原则；古松/枯树的姿态和空洞是自习结构约束，不是 FYZ 或 strggle李青的原工程复刻。灰模尚未通过形态验收。</p><p>04树皮保持冻结。这里仅留 u周向/v局部弧长/growthV累计弧长/junction衔接接口，没有加载失败树皮为成品。</p>';document.querySelector('#tree-source-close').onclick=()=>document.querySelector('#source-dialog').close();api.treeReady=true;}
window.addEventListener('vegetation-study-ready',start,{once:true});if(window.__plantStudy?.study)start();
